import React from 'react'
import { createRoot } from 'react-dom/client'
import './index.css'
import App from './App'

const rootElement = document.getElementById('root')

if (!rootElement) {
    throw new Error('Elemento root não encontrado.')
}

createRoot(rootElement).render(
    <React.StrictMode>
        <App />
    </React.StrictMode>
)
